sp_widget.client_script:
function($timeout, $scope) {
  var c = this;
  /* I6: Idea-lifecycle states (value -> chip slug). */
  var SLUGS = {'1': 'submitted', '-2': 'need_info', '-1': 'under_review', '2': 'in_backlog',
               '4': 'planned', '5': 'in_development', '10': 'on_hold', '3': 'completed', '7': 'unlikely',
               '9': 'cancelled', '8': 'duplicate'};
  var STATE_LABELS = { submitted: 'Submitted', under_review: 'Under Review', in_backlog: 'In Backlog',
                       planned: 'Planned', in_development: 'In Development', completed: 'Completed',
                       need_info: 'Need more information', unlikely: 'Unlikely to implement',
                       cancelled: 'Cancelled', duplicate: 'Duplicate', on_hold: 'On Hold' };

  /* ==== B147 (STRY0012133): saved view - people x Geo scope, state chip, sort ==== */
  var FIRST = { number: 'desc', title: 'asc', submitted_by: 'asc', geo: 'asc', state: 'asc',
                submitted: 'desc', updated: 'desc' };
  c.sortKeys = [
    { key: 'submitted', label: 'Submitted' }, { key: 'updated', label: 'Updated' },
    { key: 'number', label: 'Number' }, { key: 'title', label: 'Title' },
    { key: 'submitted_by', label: 'Submitted by' }, { key: 'geo', label: 'Target Geo' },
    { key: 'state', label: 'State' }
  ];
  var DIR_WORDS = {
    submitted: { desc: 'Newest first', asc: 'Oldest first' },
    updated: { desc: 'Recently updated first', asc: 'Least recently updated first' },
    number: { desc: 'Highest first', asc: 'Lowest first' },
    title: { asc: 'A to Z', desc: 'Z to A' },
    submitted_by: { asc: 'A to Z', desc: 'Z to A' },
    geo: { asc: 'A to Z', desc: 'Z to A' },
    state: { asc: 'Journey order', desc: 'Reverse journey order' }
  };
  var SORT_PHRASE = {
    submitted: { desc: 'newest first', asc: 'oldest first' },
    updated: { desc: 'sorted by last updated', asc: 'sorted by least recently updated' },
    number: { desc: 'sorted by number, highest first', asc: 'sorted by number, lowest first' },
    title: { asc: 'sorted by title A to Z', desc: 'sorted by title Z to A' },
    submitted_by: { asc: 'sorted by submitter A to Z', desc: 'sorted by submitter Z to A' },
    geo: { asc: 'sorted by Target Geo A to Z', desc: 'sorted by Target Geo Z to A' },
    state: { asc: 'in journey order', desc: 'in reverse journey order' }
  };

  c.loading = false;
  c.loadError = false;
  var base = window.location.origin + window.location.pathname;

  function clone(o) { return JSON.parse(JSON.stringify(o)); }
  function defaultView() {
    return { v: 1, people: { mode: 'include', ids: ['me'] }, geo: [], state: '',
             sort: { key: 'submitted', dir: 'desc' } };
  }
  function curView() { return (c.data && c.data.view) || defaultView(); }
  function isDefaultView(v) {
    return v.people.mode === 'include' && v.people.ids.length === 1 && v.people.ids[0] === 'me' &&
           !v.geo.length && !v.state && v.sort.key === 'submitted' && v.sort.dir === 'desc';
  }
  function trunc(s, n) { s = String(s || ''); return s.length > n ? s.slice(0, n - 1) + '…' : s; }

  function decorateItems() {
    var items = (c.data && c.data.items) || [];
    for (var i = 0; i < items.length; i++) {
      var it = items[i];
      it.slug = SLUGS[String(it.state)] || 'submitted';
      it.created_d = String(it.created || '').split(' ')[0];
      it.updated_d = String(it.updated || '').split(' ')[0];
      it.by_label = it.mine ? 'You' : (it.by || 'Unknown');
      /* I13 R3c: the shareable status link is the number lookup on My Engagements */
      it.track_url = base + '?id=ptag_status&number=' + encodeURIComponent(it.number || '');
    }
  }

  /* ---- I14 R4: client-side pagination over the returned rows ---- */
  c.sizes = [10, 20, 50, 100];
  c.pageSize = 10;
  c.page = 1;
  c.pageItems = [];
  c.total = 0; c.pageCount = 1; c.rangeStart = 0; c.rangeEnd = 0;
  function recomputePage() {
    var items = (c.data && c.data.items) || [];
    c.total = items.length;
    var size = parseInt(c.pageSize, 10) || 10;
    c.pageCount = Math.max(1, Math.ceil(c.total / size));
    if (c.page > c.pageCount) { c.page = c.pageCount; }
    if (c.page < 1) { c.page = 1; }
    var from = (c.page - 1) * size;
    c.pageItems = items.slice(from, from + size);
    c.rangeStart = c.total ? (from + 1) : 0;
    c.rangeEnd = Math.min(from + size, c.total);
  }
  c.setSize = function() { c.pageSize = parseInt(c.pageSize, 10) || 10; c.page = 1; recomputePage(); };
  c.prevPage = function() { if (c.page > 1) { c.page--; recomputePage(); } };
  c.nextPage = function() { if (c.page < c.pageCount) { c.page++; recomputePage(); } };

  /* ---- names for chips, triggers and the sentence ---- */
  var nameMap = {};
  function learnNames() {
    var lp = (c.data && c.data.view_labels && c.data.view_labels.people) || [];
    for (var i = 0; i < lp.length; i++) { nameMap[lp[i].id] = lp[i]; }
    var po = c.people.opts || [];
    for (var j = 0; j < po.length; j++) { nameMap[po[j].id] = po[j]; }
  }
  var geoMap = {};
  function learnGeos() {
    var lg = (c.data && c.data.view_labels && c.data.view_labels.geo) || [];
    for (var i = 0; i < lg.length; i++) { geoMap[lg[i].id] = lg[i].label; }
    var go = c.geo.opts || [];
    for (var j = 0; j < go.length; j++) { geoMap[go[j].id] = go[j].label; }
    geoMap.none = 'Not set';
  }
  function personName(id) { var p = nameMap[id]; return p ? p.name : 'Unknown person'; }
  c.personName = personName;
  c.personInactive = function(id) { var p = nameMap[id]; return !!(p && p.active === false); };
  function geoName(id) { return geoMap[id] || (id === 'none' ? 'Not set' : 'Unknown Geo'); }
  c.geoName = geoName;

  function listNames(names) {
    if (names.length <= 2) { return names.join(' and '); }
    var rest = names.length - 2;
    return names.slice(0, 2).join(', ') + ' and ' + rest + ' other' + (rest === 1 ? '' : 's');
  }
  function orList(items) {
    if (items.length <= 1) { return items.join(''); }
    return items.slice(0, -1).join(', ') + ' or ' + items[items.length - 1];
  }
  function peopleNames(v) {
    var out = [], ids = v.people.ids;
    var hasMe = ids.indexOf('me') > -1;
    if (hasMe) { out.push('you'); }
    for (var i = 0; i < ids.length; i++) { if (ids[i] !== 'me') { out.push(personName(ids[i])); } }
    return out;
  }
  function geoPhrase(v) {
    var real = [], none = false;
    for (var i = 0; i < v.geo.length; i++) {
      if (v.geo[i] === 'none') { none = true; } else { real.push(geoName(v.geo[i])); }
    }
    if (!real.length) { return 'with no Geo'; }
    if (none) { return 'in ' + real.join(', ') + ' or with no Geo'; }
    return 'in ' + orList(real);
  }
  function sentenceParts(v) {
    if (isDefaultView(v)) {
      return [{ t: 'Requests you submitted, newest first. Open one for live status and the conversation with PTAG.', em: false }];
    }
    var names = peopleNames(v), out = [{ t: 'Requests from ', em: false }];
    if (v.people.mode === 'include') { out.push({ t: listNames(names), em: true }); }
    else { out.push({ t: names.length ? 'everyone except ' + listNames(names) : 'everyone', em: true }); }
    if (v.geo.length) { out.push({ t: ', ', em: false }); out.push({ t: geoPhrase(v), em: true }); }
    if (v.state) { out.push({ t: ', ', em: false }); out.push({ t: 'that are ' + (STATE_LABELS[v.state] || v.state), em: true }); }
    var ph = (SORT_PHRASE[v.sort.key] || SORT_PHRASE.submitted)[v.sort.dir] || 'newest first';
    out.push({ t: ', ', em: false }); out.push({ t: ph, em: true }); out.push({ t: '.', em: false });
    return out;
  }
  function plain(parts) { var s = ''; for (var i = 0; i < parts.length; i++) { s += parts[i].t; } return s; }

  function peopleLabel(v) {
    var ids = v.people.ids;
    if (v.people.mode === 'exclude') {
      if (!ids.length) { return 'Everyone'; }
      return 'Everyone except ' + (ids.length === 1 ? (ids[0] === 'me' ? 'me' : trunc(personName(ids[0]), 22)) : ids.length);
    }
    if (ids.indexOf('me') > -1) { return ids.length === 1 ? 'Me' : 'Me +' + (ids.length - 1); }
    if (ids.length === 1) { return trunc(personName(ids[0]), 22); }
    return ids.length + ' people';
  }
  function peopleFull(v) {
    var names = peopleNames(v);
    if (v.people.mode === 'exclude') { return names.length ? 'everyone except ' + listNames(names) : 'everyone'; }
    return names.length === 1 && names[0] === 'you' ? 'Me' : listNames(names);
  }
  function geoLabel(v) {
    if (!v.geo.length) { return 'Any'; }
    if (v.geo.length >= 3) { return v.geo.length + ' selected'; }
    var out = [];
    for (var i = 0; i < v.geo.length; i++) { out.push(trunc(geoName(v.geo[i]), 18)); }
    return out.join(', ');
  }

  /* everything the template reads, rebuilt once per response (not per digest) */
  function refreshDerived() {
    var v = curView();
    learnNames(); learnGeos();
    c.isDefault = !!(c.data && c.data.view_is_default);
    c.linked = (c.data && c.data.linked) || null;
    c.sentence = sentenceParts(v);
    c.sentencePlain = plain(c.sentence);
    c.pLabel = peopleLabel(v);
    c.pAria = 'Submitted by: ' + peopleFull(v) + '. Change';
    c.gLabel = geoLabel(v);
    var gl = [];
    for (var i = 0; i < v.geo.length; i++) { gl.push(geoName(v.geo[i])); }
    c.gAria = 'Target Geo: ' + (gl.length ? gl.join(', ') : 'Any') + '. Change';
    c.pActive = !(v.people.mode === 'include' && v.people.ids.length === 1 && v.people.ids[0] === 'me');
    c.gActive = v.geo.length > 0;
    c.sortActive = !(v.sort.key === 'submitted' && v.sort.dir === 'desc');
    c.filterCount = (c.pActive ? 1 : 0) + (c.gActive ? 1 : 0) + (c.sortActive ? 1 : 0);
    c.stateLabel = STATE_LABELS[v.state] || '';
    c.linkedStateLabel = (c.linked && c.linked.slug) ? (STATE_LABELS[c.linked.slug] || '') : '';
    c.sortSel = c.linked ? 'submitted' : v.sort.key;
    c.sortDirWord = (DIR_WORDS[c.sortSel] || DIR_WORDS.submitted)[c.linked ? 'desc' : v.sort.dir];
    var items = (c.data && c.data.items) || [];
    c.empty = '';
    if (c.loadError) { c.empty = 'error'; }
    else if (!items.length) {
      if (c.linked) { c.empty = c.linked.kind === 'number' ? 'number' : (c.linked.kind === 'awaiting' ? 'awaiting' : 'linkstate'); }
      else if (c.isDefault) { c.empty = 'first'; }
      else if (v.state) { c.empty = 'state'; }
      else { c.empty = 'view'; }
    }
  }

  /* ---- one round trip per committed change; stale responses are dropped ---- */
  var seq = 0, lastPayload = null;
  c.live = '';
  function announce(msg) {
    c.live = '';
    $timeout(function() { c.live = msg; }, 80);
  }
  /* the updating state: on from the digest that starts a refetch until its answer is applied, and held
     for at least BUSY_MIN ms so a fast answer does not flicker. c.loading keeps its own meaning. */
  var BUSY_MIN = 300, busyAt = 0, busyTimer = null;
  c.busy = false;
  function busyOn() {
    if (busyTimer) { $timeout.cancel(busyTimer); busyTimer = null; }
    if (!c.busy) { busyAt = Date.now(); }
    c.busy = true;
  }
  function busyOff() {
    var left = BUSY_MIN - (Date.now() - busyAt);
    if (busyTimer) { $timeout.cancel(busyTimer); busyTimer = null; }
    if (left <= 0) { c.busy = false; return; }
    busyTimer = $timeout(function() { busyTimer = null; c.busy = false; }, left);
  }
  function countMsg(d) {
    var n = (d && d.total) || 0;
    return n ? (n + ' request' + (n === 1 ? '' : 's')) : 'No requests match this view';
  }
  function applyList(d) {
    var keys = ['items', 'count', 'total', 'truncated', 'view', 'view_source', 'view_is_default', 'view_labels',
                'linked', 'number', 'number_invalid', 'number_not_found', 'awaiting', 'awaiting_records',
                'awaiting_comments', 'chips', 'active', 'browse', 'view_saved'];
    for (var i = 0; i < keys.length; i++) { c.data[keys[i]] = d[keys[i]]; }
    if (d.view_notice) { c.data.view_notice = d.view_notice; c.noticeOpen = true; }
    c.data.items = d.items || [];
    decorateItems();
    c.page = 1;
    recomputePage();
  }
  function send(payload, after) {
    var my = ++seq;
    payload.seq = my;
    lastPayload = { payload: payload, after: after };
    c.loading = true;
    c.loadError = false;
    busyOn();
    announce('Updating list');
    return c.server.get(payload).then(function(r) {
      if (my !== seq) { return; }          /* a newer request was sent: this answer is stale */
      var d = (r && r.data) || {};
      applyList(d);
      c.loading = false;
      busyOff();
      refreshDerived();
      scrollActiveChip();
      if (d.number && (c.linked && c.linked.kind === 'number')) { c.numInput = d.number; }
      if (after) { after(d); }
    }, function() {
      if (my !== seq) { return; }
      c.loading = false;
      c.loadError = true;
      busyOff();
      refreshDerived();
      announce("Couldn't load requests.");
    });
  }
  c.retry = function() {
    if (lastPayload) { var p = lastPayload.payload; delete p.seq; send(p, lastPayload.after); }
    else { send({ op: 'saved' }); }
  };

  /* URL: linked views keep their param; the saved view is never encoded in the URL */
  function setParams(fn) {
    try {
      var u = new URL(window.location.href);
      u.searchParams.set('id', 'ptag_status');
      u.searchParams['delete']('state');
      u.searchParams['delete']('number');
      u.searchParams['delete']('awaiting');
      if (fn) { fn(u.searchParams); }
      window.history.replaceState(window.history.state, '', u.toString());
    } catch (e) {}
  }
  function stripLinkParams() { setParams(null); }

  /* ---- saved-view status (pill), Reset + Undo ---- */
  c.saveState = 'idle';      /* idle | saved (2 s flash) | failed */
  c.undoOn = false;
  var flashTimer = null, undoTimer = null;
  function flashSaved(d) {
    if (flashTimer) { $timeout.cancel(flashTimer); flashTimer = null; }
    if (d.view_saved === false) { c.saveState = 'failed'; return; }
    if (d.view_is_default) { c.saveState = 'idle'; return; }
    c.saveState = 'saved';
    flashTimer = $timeout(function() { c.saveState = 'idle'; }, 2000);
  }
  function commitView(v, after) {
    stripLinkParams();
    if (undoTimer) { $timeout.cancel(undoTimer); undoTimer = null; }
    c.undoOn = false;
    send({ op: 'view', view_json: JSON.stringify(v) }, function(d) {
      flashSaved(d);
      var msg = countMsg(d);
      if (d.view_saved === false) { msg += ". Couldn't save your view. It applies for this visit only."; }
      else if (!d.view_is_default) { msg += '. View saved'; }
      announce(msg);
      if (after) { after(d); }
    });
  }
  function focusEl(sel) {
    $timeout(function() { var el = document.querySelector(sel); if (el && el.focus) { el.focus(); } }, 30);
  }
  c.reset = function() {
    var prev = clone(curView());
    stripLinkParams();
    c.numInput = '';
    if (undoTimer) { $timeout.cancel(undoTimer); }
    send({ op: 'reset' }, function(d) {
      c.saveState = d.view_saved === false ? 'failed' : 'idle';
      c.undoView = prev;
      c.undoOn = !isDefaultView(prev);
      undoTimer = $timeout(function() { c.undoOn = false; }, 10000);
      focusEl('#pt-myeng-h');
      announce('Showing requests submitted by you. ' + countMsg(d) + '.' +
               (c.undoOn ? ' View reset. Undo available for 10 seconds.' : ''));
    });
  };
  c.undo = function() {
    if (!c.undoView) { return; }
    var v = c.undoView;
    c.undoView = null;
    c.undoOn = false;
    commitView(v);
  };
  c.dismissNotice = function() { c.noticeOpen = false; };

  /* ---- state chips (part of the saved view, J1) + the personal awaiting worklist ---- */
  c.pickChip = function(ch) {
    if (ch && ch.awaiting) { c.applyAwaiting(); return; }
    var v = clone(curView());
    v.state = (ch && !ch.all) ? ch.slug : '';
    c.numInput = '';
    c.numErr = false;
    c.lastChanged = 'state';
    commitView(v);
  };
  c.applyAwaiting = function() {
    c.numInput = '';
    c.numErr = false;
    setParams(function(sp) { sp.set('awaiting', '1'); });
    send({ op: 'awaiting' }, function(d) { announce(d.total ? countMsg(d) + ' waiting on your reply' : "You're all caught up"); });
  };
  c.backToView = function() {
    stripLinkParams();
    c.numInput = '';
    c.numErr = false;
    send({ op: 'saved' }, function(d) { announce(countMsg(d)); });
  };
  c.showAllStates = function() { var v = clone(curView()); v.state = ''; commitView(v); };

  /* ---- number lookup: across all requests, a Linked view (never saved) ---- */
  c.numInput = (c.data && c.data.number) || '';
  c.numErr = false;
  c.numTouch = function() { if (c.numErr) { c.numErr = false; } };
  function _numShake() { c.numErr = false; $timeout(function() { c.numErr = true; }); }
  c.applyNumber = function() {
    var v = String(c.numInput || '').trim().toUpperCase();
    c.numInput = v;
    if (!/^[PTAG0-9*]+$/.test(v) || v.replace(/\*/g, '') === '') { _numShake(); return; }
    v = v.replace(/\*{2,}/g, '*');
    if (v.indexOf('*') === -1 && !/^PTAG\d{4,}$/.test(v)) { _numShake(); return; }
    c.numInput = v;
    c.numErr = false;
    setParams(function(sp) { sp.set('number', v); });
    send({ op: 'number', number: v }, function(d) {
      announce(d.number_not_found ? 'No request matches ' + v : countMsg(d));
    });
  };
  c.clearNumber = function() { c.backToView(); };

  /* ---- sort (in the query; header buttons, or the Sort by menu under 980 px) ---- */
  c.sortBy = function(key) {
    var v = clone(curView());
    if (!c.linked && v.sort.key === key) { v.sort.dir = v.sort.dir === 'asc' ? 'desc' : 'asc'; }
    else { v.sort = { key: key, dir: FIRST[key] }; }
    c.lastChanged = 'sort';
    commitView(v);
  };
  c.pickSortKey = function() { if (c.sortSel) { c.sortBy(c.sortSel); } };
  c.flipSort = function() {
    var v = clone(curView());
    v.sort.dir = v.sort.dir === 'asc' ? 'desc' : 'asc';
    commitView(v);
  };
  c.isSorted = function(key) { return c.linked ? key === 'submitted' : curView().sort.key === key; };
  c.isAsc = function() { return !c.linked && curView().sort.dir === 'asc'; };
  c.ariaSort = function(key) {
    if (!c.isSorted(key)) { return 'none'; }
    return c.isAsc() ? 'ascending' : 'descending';
  };

  /* ---- People + Geo popovers (desktop) / one sheet (under 620 px) ---- */
  c.pop = '';
  c.d = null;
  c.people = { opts: null, loading: false, q: '', view: [], focus: 0, msg: '' };
  c.geo = { opts: null, loading: false, q: '', view: [] };
  var narrowMq = window.matchMedia ? window.matchMedia('(max-width: 619px)') : null;
  function isNarrow() { return !!(narrowMq && narrowMq.matches); }
  function draftOf(v) { return { people: clone(v.people), geo: v.geo.slice(), sort: clone(v.sort) }; }
  function fold(s) {
    s = String(s || '');
    try { s = s.normalize('NFD').replace(/[̀-ͯ]/g, ''); } catch (e) {}
    return s.toLowerCase();
  }
  function loadPeople() {
    if (c.people.opts || c.people.loading) { return; }
    c.people.loading = true;
    c.server.get({ action: 'people_options' }).then(function(r) {
      c.people.opts = ((r && r.data) || {}).people_options || [];
      c.people.loading = false;
      learnNames();
      c.filterPeople();
    }, function() { c.people.loading = false; c.people.opts = []; c.filterPeople(); });
  }
  function loadGeo() {
    c.geo.loading = true;
    c.server.get({ action: 'geo_options', view_json: JSON.stringify(curView()) }).then(function(r) {
      c.geo.opts = ((r && r.data) || {}).geo_options || [];
      c.geo.loading = false;
      learnGeos();
      c.filterGeo();
      if (c.pop === 'geo') { focusEl('#pt-pop-geo input[type="checkbox"]'); }
    }, function() { c.geo.loading = false; c.geo.opts = c.geo.opts || []; c.filterGeo(); });
  }
  c.filterPeople = function() {
    var q = fold(c.people.q).replace(/^\s+|\s+$/g, '');
    var src = c.people.opts || [];
    c.people.view = !q ? src.slice() : src.filter(function(p) {
      return fold(p.name).indexOf(q) > -1 || (p.me && 'me'.indexOf(q) === 0);
    });
    c.people.focus = 0;
    var n = c.people.view.length;
    c.people.msg = n + (n === 1 ? ' person' : ' people');
  };
  c.filterGeo = function() {
    var q = fold(c.geo.q).replace(/^\s+|\s+$/g, '');
    var src = c.geo.opts || [];
    c.geo.view = !q ? src.slice() : src.filter(function(g) { return g.id === 'none' || fold(g.label).indexOf(q) > -1; });
  };
  function placePop(which) {
    /* anchored below its trigger, left-aligned, clamped to the bar, flips up if there
       is no room below (spec 5.2) */
    try {
      var t = document.getElementById(which === 'geo' ? 'pt-vt-geo' : 'pt-vt-people');
      var bar = document.getElementById('pt-viewbar');
      var r = t.getBoundingClientRect(), br = bar.getBoundingClientRect();
      var w = Math.min(420, br.width);
      var left = r.left - br.left;
      if (left + w > br.width) { left = Math.max(0, br.width - w); }
      c.popLeft = Math.round(left);
      c.popTop = Math.round(r.bottom - br.top + 8);
      c.popUp = (window.innerHeight - r.bottom < 470) && (r.top > 470);
      c.popBottom = Math.round(br.bottom - r.top + 8);
    } catch (e) { c.popUp = false; c.popLeft = 0; c.popTop = 48; c.popBottom = 48; }
  }
  c.popStyle = function() {
    if (c.pop === 'sheet') { return {}; }
    return c.popUp ? { left: c.popLeft + 'px', bottom: c.popBottom + 'px', top: 'auto' }
                   : { left: c.popLeft + 'px', top: c.popTop + 'px' };
  };
  c.openPeople = function() {
    if (isNarrow()) { c.openSheet(); return; }
    if (c.pop === 'people') { c.cancelPop(); return; }
    c.d = draftOf(curView());
    c.people.q = '';
    placePop('people');
    c.pop = 'people';
    loadPeople();
    c.filterPeople();
    focusEl('#pt-psearch');
  };
  c.openGeo = function() {
    if (isNarrow()) { c.openSheet(); return; }
    if (c.pop === 'geo') { c.cancelPop(); return; }
    c.d = draftOf(curView());
    c.geo.q = '';
    placePop('geo');
    c.pop = 'geo';
    loadGeo();
    c.filterGeo();
    focusEl('#pt-pop-geo');
  };
  c.openSheet = function() {
    c.d = draftOf(curView());
    c.people.q = '';
    c.pop = 'sheet';
    lock(true);
    loadPeople();
    loadGeo();
    c.filterPeople();
    c.filterGeo();
    focusEl('#pt-sheet-t');
  };
  c.changeFilters = function() { if (c.lastChanged === 'geo') { c.openGeo(); } else { c.openPeople(); } };
  c.addPeople = function() { c.openPeople(); };
  function focusTrigger(which) {
    if (which === 'geo') { focusEl('#pt-vt-geo'); }
    else if (which === 'sheet') { focusEl('#pt-vt-filters'); }
    else { focusEl('#pt-vt-people'); }
  }
  c.cancelPop = function(noFocus) {
    var was = c.pop;
    c.pop = '';
    c.d = null;
    if (was === 'sheet') { lock(false); }
    if (!noFocus && was) { focusTrigger(was); }
  };
  c.canApply = function() {
    return !!c.d && !(c.d.people.mode === 'include' && !c.d.people.ids.length);
  };
  c.applyPop = function() {
    if (!c.canApply()) { return; }
    var v = clone(curView());
    var was = c.pop;
    if (was === 'people' || was === 'sheet') { v.people = clone(c.d.people); }
    if (was === 'geo' || was === 'sheet') { v.geo = c.d.geo.slice(); }
    if (was === 'sheet') { v.sort = clone(c.d.sort); }
    c.lastChanged = was === 'geo' ? 'geo' : 'people';
    c.pop = '';
    c.d = null;
    if (was === 'sheet') { lock(false); }
    focusTrigger(was);
    commitView(v);
  };
  c.popKey = function(ev) {
    if (ev.keyCode === 27) { ev.preventDefault(); ev.stopPropagation(); c.cancelPop(); return; }
    if (ev.keyCode === 13 && (ev.ctrlKey || ev.metaKey)) { ev.preventDefault(); c.applyPop(); return; }
    if (ev.keyCode === 9 && c.pop === 'sheet') {
      /* the sheet is modal (aria-modal): keep Tab inside it */
      var root = document.getElementById('pt-pop-sheet');
      if (!root) { return; }
      var f = root.querySelectorAll('button:not([disabled]), input, select, [tabindex="0"]');
      if (!f.length) { return; }
      var first = f[0], last = f[f.length - 1];
      if (ev.shiftKey && document.activeElement === first) { ev.preventDefault(); last.focus(); }
      else if (!ev.shiftKey && document.activeElement === last) { ev.preventDefault(); first.focus(); }
    }
  };
  function onDocDown(ev) {
    if (c.pop !== 'people' && c.pop !== 'geo') { return; }
    var t = ev.target;
    if (t && t.closest && (t.closest('.pt-pop') || t.closest('.pt-vtrigger'))) { return; }
    $scope.$apply(function() { c.cancelPop(true); });
  }
  document.addEventListener('mousedown', onDocDown, true);

  /* people: draft selection + a listbox with one Tab stop (roving focus) */
  c.isSel = function(p) { return !!c.d && c.d.people.ids.indexOf(p.id) > -1; };
  c.togglePerson = function(p, idx) {
    if (!c.d) { return; }
    var ids = c.d.people.ids, i = ids.indexOf(p.id);
    if (i > -1) { ids.splice(i, 1); } else { ids.push(p.id); }
    if (idx != null) { c.people.focus = idx; }
  };
  c.removeDraftPerson = function(id) {
    if (!c.d) { return; }
    var i = c.d.people.ids.indexOf(id);
    if (i > -1) { c.d.people.ids.splice(i, 1); }
  };
  c.clearDraftPeople = function() { if (c.d) { c.d.people.ids = []; } };
  function focusOpt(i) {
    $timeout(function() { var el = document.getElementById('pt-popt-' + i); if (el) { el.focus(); } }, 0);
  }
  c.searchKey = function(ev) {
    if (ev.keyCode === 40 && c.people.view.length) { ev.preventDefault(); c.people.focus = 0; focusOpt(0); }
  };
  c.listKey = function(ev) {
    var n = c.people.view.length;
    if (!n) { return; }
    var f = c.people.focus, k = ev.keyCode;
    if (k === 40) { f = Math.min(n - 1, f + 1); }
    else if (k === 38) {
      if (f === 0) { ev.preventDefault(); focusEl('#pt-psearch'); return; }
      f = f - 1;
    }
    else if (k === 36) { f = 0; }
    else if (k === 35) { f = n - 1; }
    else if ((k === 32 || k === 13) && !(ev.ctrlKey || ev.metaKey)) {
      ev.preventDefault();
      c.togglePerson(c.people.view[f], f);
      return;
    } else { return; }
    ev.preventDefault();
    c.people.focus = f;
    focusOpt(f);
  };
  c.draftSentence = function() {
    if (!c.d) { return ''; }
    var v = clone(curView());
    v.people = c.d.people;
    if (c.pop === 'sheet') { v.geo = c.d.geo; v.sort = c.d.sort; }
    if (v.people.mode === 'include' && !v.people.ids.length) { return 'Pick at least one person, or choose Everyone except.'; }
    return plain(sentenceParts(v));
  };

  /* geo: native checkboxes */
  c.isGeo = function(g) { return !!c.d && c.d.geo.indexOf(g.id) > -1; };
  c.toggleGeo = function(g) {
    if (!c.d) { return; }
    var i = c.d.geo.indexOf(g.id);
    if (i > -1) { c.d.geo.splice(i, 1); } else { c.d.geo.push(g.id); }
  };
  c.clearGeo = function() { if (c.d) { c.d.geo = []; } };

  /* sheet sort */
  c.sheetSortKey = function() { if (c.d) { c.d.sort = { key: c.d.sort.key, dir: FIRST[c.d.sort.key] }; } };
  c.sheetFlip = function() { if (c.d) { c.d.sort.dir = c.d.sort.dir === 'asc' ? 'desc' : 'asc'; } };
  c.dirWord = function(s) { return s ? (DIR_WORDS[s.key] || DIR_WORDS.submitted)[s.dir] : ''; };

  /* table row: a mouse convenience that delegates to the Number button */
  c.rowClick = function(ev, it) {
    var t = ev && ev.target;
    if (t && t.closest && t.closest('button, a')) { return; }
    c.open(it);
  };

  /* ---- I11 detail modal + comment thread -------------------------------- */
  function blankDm() {
    return { open: false, busy: false, posting: false, detail: null, thread: [], text: '',
             error: '', num: '', files: [], uploading: false, fileErr: '' };
  }

  /* ---- I30 attachments -------------------------------------------------- */
  c.fileSize = function(n) {
    n = parseInt(n, 10) || 0;
    if (n < 1024) { return n + ' B'; }
    if (n < 1048576) { return Math.round(n / 1024) + ' KB'; }
    return (Math.round(n / 104857.6) / 10) + ' MB';
  };

  function allowed(name) {
    var acc = String((c.data && c.data.attach && c.data.attach.accept) || '').split(',');
    var dot = String(name || '').lastIndexOf('.');
    if (dot < 0) { return false; }
    var ext = String(name).substring(dot).toLowerCase();
    for (var i = 0; i < acc.length; i++) {
      if (acc[i].trim().toLowerCase() === ext) { return true; }
    }
    return false;
  }

  c.pickFile = function() {
    var el = document.getElementById('pt-file-input');
    if (!el) { return; }
    if (!el.getAttribute('data-pt-bound')) {
      el.setAttribute('data-pt-bound', '1');
      el.addEventListener('change', function() { c.onFiles(el.files); });
    }
    el.value = '';
    el.click();
  };

  function uploadOne(file, sysId) {
    var tok = '';
    try { tok = window.g_ck || (window.NOW && window.NOW.user_token) || ''; } catch (e) {}
    var url = '/api/now/attachment/file?table_name=x_snc_ptag_engage_engagement_request' +
              '&table_sys_id=' + encodeURIComponent(sysId) +
              '&file_name=' + encodeURIComponent(file.name);
    return fetch(url, {
      method: 'POST',
      credentials: 'same-origin',
      headers: {
        'Content-Type': file.type || 'application/octet-stream',
        'X-UserToken': tok,
        'Accept': 'application/json'
      },
      body: file
    }).then(function(res) {
      if (!res.ok) { throw new Error('upload failed (' + res.status + ')'); }
      return res;
    });
  }

  c.onFiles = function(fileList) {
    if (!c.dm.detail || !c.dm.detail.can_act) { return; }
    var maxMb = (c.data && c.data.attach && c.data.attach.max_mb) || 10;
    var files = [], i;
    for (i = 0; i < fileList.length; i++) { files.push(fileList[i]); }
    if (!files.length) { return; }

    for (i = 0; i < files.length; i++) {
      if (!allowed(files[i].name)) {
        $timeout(function() { c.dm.fileErr = 'That file type is not accepted.'; });
        return;
      }
      if (files[i].size > maxMb * 1048576) {
        $timeout(function() { c.dm.fileErr = 'Files must be under ' + maxMb + ' MB.'; });
        return;
      }
    }

    $timeout(function() { c.dm.uploading = true; c.dm.fileErr = ''; });
    var sysId = c.dm.detail.id;
    var chain = Promise.resolve();
    files.forEach(function(f) {
      chain = chain.then(function() { return uploadOne(f, sysId); });
    });
    chain.then(function() {
      return c.server.get({ action: 'attach_list', sys_id: sysId });
    }).then(function(r) {
      $timeout(function() {
        c.dm.files = ((r && r.data) || {}).attachments || c.dm.files;
        c.dm.uploading = false;
      });
    })['catch'](function(err) {
      $timeout(function() {
        c.dm.uploading = false;
        c.dm.fileErr = 'Could not upload that file. ' +
                       (String(err && err.message || '').indexOf('403') > -1
                        ? 'You may not have permission.' : 'Please try again.');
      });
    });
  };

  c.removeFile = function(f) {
    if (!c.dm.detail || c.dm.uploading) { return; }
    c.dm.uploading = true;
    c.server.get({ action: 'attach_delete', sys_id: c.dm.detail.id,
                   attachment_id: f.id }).then(function(r) {
      var d = (r && r.data) || {};
      c.dm.uploading = false;
      if (d.error) {
        c.dm.fileErr = (d.error === 'locked')
          ? 'This engagement is closed and can no longer be changed.'
          : 'Could not remove that file.';
        if (d.attachments) { c.dm.files = d.attachments; }
        return;
      }
      c.dm.files = d.attachments || [];
      c.dm.fileErr = '';
    }, function() {
      c.dm.uploading = false;
      c.dm.fileErr = 'Could not remove that file.';
    });
  };
  c.dm = blankDm();

  function lock(on) {
    try { document.body.classList[on ? 'add' : 'remove']('pt-modal-open'); } catch (e) {}
  }

  function decorate(d) {
    if (!d) { return d; }
    d.slug = SLUGS[String(d.state)] || 'submitted';
    d.submitted_d = String(d.submitted || '').split(' ')[0];
    d.by_label = d.mine ? 'You' : (d.submitted_by || 'Unknown');
    return d;
  }

  function revealNewest() {
    $timeout(function() {
      var thread = document.querySelector('.pt-modal--eng .pt-thread');
      var body = document.querySelector('.pt-modal--eng .pt-modal__body');
      if (!thread || !body) { return; }
      var last = thread.lastElementChild;
      if (!last) { return; }
      var br = body.getBoundingClientRect();
      var lr = last.getBoundingClientRect();
      var delta = (lr.bottom - br.bottom) + 16;
      if (delta > 0) { body.scrollTop = body.scrollTop + delta; }
    }, 60);
  }

  var openerEl = null;
  c.open = function(it) {
    openerEl = document.activeElement;
    c.dm = blankDm();
    c.dm.open = true;
    c.dm.busy = true;
    c.dm.num = it.number;
    lock(true);
    focusEl('.pt-modal--eng .pt-modal__close');
    c.server.get({ action: 'detail', sys_id: it.id }).then(function(r) {
      if (!c.dm.open) { return; }
      var d = (r && r.data) || {};
      if (d.error || !d.detail) {
        c.dm.error = 'Could not load this engagement.';
        c.dm.busy = false;
        return;
      }
      c.dm.detail = decorate(d.detail);
      c.dm.thread = d.thread || [];
      c.dm.files = d.attachments || [];
      c.dm.busy = false;
      /* I20: the server recorded the read receipt (own requests only) */
      if (it.mine) { it.unread = false; }
    }, function() {
      c.dm.error = 'Could not load this engagement.';
      c.dm.busy = false;
    });
  };

  c.close = function() {
    lock(false);
    c.dm = blankDm();
    var back = openerEl;
    openerEl = null;
    if (back && back.focus) { $timeout(function() { try { back.focus(); } catch (e) {} }, 30); }
  };

  c.dmKeydown = function(ev) {
    if (ev.keyCode === 27) { ev.preventDefault(); ev.stopPropagation(); c.close(); }
  };

  c.cardKey = function(ev, it) {
    if (ev.keyCode === 13 || ev.keyCode === 32) { ev.preventDefault(); c.open(it); }
  };

  c.post = function() {
    var txt = String(c.dm.text || '').trim();
    if (!txt || c.dm.posting || !c.dm.detail || !c.dm.detail.can_act) { return; }
    c.dm.posting = true;
    c.dm.error = '';
    c.server.get({ action: 'comment', sys_id: c.dm.detail.id, text: txt }).then(function(r) {
      var d = (r && r.data) || {};
      c.dm.posting = false;
      if (d.error || !d.posted) {
        c.dm.error = (d.error === 'empty_comment') ? 'Write a comment first.'
                   : (d.error === 'locked') ? 'This engagement is closed and can no longer be changed.'
                   : 'Could not post your comment.';
        if (d.error === 'locked' && d.detail) { c.dm.detail = decorate(d.detail); }
        return;
      }
      c.dm.detail = decorate(d.detail || c.dm.detail);
      c.dm.thread = d.thread || c.dm.thread;
      c.dm.files = d.attachments || c.dm.files;
      c.dm.text = '';
      var mine = (c.data && c.data.items) || [];
      for (var mi = 0; mi < mine.length; mi++) {
        if (mine[mi].id === c.dm.detail.id) {
          mine[mi].reply_pending = false;
          mine[mi].unread = false;
          mine[mi].unanswered = 0;
          mine[mi].comments = (mine[mi].comments || 0) + 1;
          break;
        }
      }
      revealNewest();
    }, function() {
      c.dm.posting = false;
      c.dm.error = 'Could not post your comment.';
    });
  };

  c.copy = function(it) {
    copyText(it.track_url, function(ok) {
      $timeout(function() { it.copied = ok; });
      $timeout(function() { it.copied = false; }, 2200);
    });
  };

  function copyText(txt, done) {
    function fallback() {
      try {
        var ta = document.createElement('textarea');
        ta.value = txt;
        ta.setAttribute('readonly', '');
        ta.style.position = 'fixed';
        ta.style.opacity = '0';
        document.body.appendChild(ta);
        ta.select();
        var ok = document.execCommand('copy');
        document.body.removeChild(ta);
        done(!!ok);
      } catch (e) { done(false); }
    }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(txt).then(function() { done(true); }, fallback);
    } else { fallback(); }
  }

  $scope.$on('$destroy', function() {
    document.removeEventListener('mousedown', onDocDown, true);
    lock(false);
  });

  /* under 620px the chips are one scrolling row: keep the active one in view */
  function scrollActiveChip() {
    if (!isNarrow()) { return; }
    $timeout(function() {
      var a = document.querySelector('.pt-myeng .pt-chipset .pt-fchip.is-active');
      var row = a && a.parentNode;
      if (row && row.scrollWidth > row.clientWidth) { row.scrollLeft = Math.max(0, a.offsetLeft - 16); }
    }, 60);
  }

  /* first render */
  decorateItems();
  recomputePage();
  refreshDerived();
  scrollActiveChip();
  c.noticeOpen = !!(c.data && c.data.view_notice);
}

sp_widget.script:
(function() {
  /* I11 + B147 (STRY0012133, 2026-09-29): My Engagements list + detail modal +
     customer-visible comments, now driven by a SAVED VIEW.
     Contract:
       (no input)             -> initial load. A ?number= / ?awaiting=1 / ?state= URL is a
                                 LINKED view (temporary, never saved). Otherwise the viewer's
                                 saved view (pref ptag.hub.myeng.view) or the default view
                                 "Submitted by me".
       input.op='view'        -> input.view_json = the full view. Validate, SAVE, query. One
                                 round trip, so the saved view and the list cannot disagree.
       input.op='reset'       -> clear the pref, default view.
       input.op='saved'       -> the saved view (Back to your view / Try again).
       input.op='number'      -> linked number lookup across ALL requests the viewer can read.
       input.op='awaiting'    -> linked: the viewer's own requests waiting on their reply.
       input.seq              -> echoed as data.seq so the client drops stale responses.
       action 'people_options' / 'geo_options' -> the picker lists (lazy).
       action 'detail'        -> READ guard (GlideRecordSecure: the table ACLs decide) +
                                 data.detail (WHITELIST) + data.thread.
       action 'comment' / attach_* -> WRITE guard PTAGHubAccess.canAct (submitter or PTAG
                                 roles) - unchanged.
     VISIBILITY RULE (I7): score / score_band / scoring_version and work_notes (AI drafts)
     are NEVER part of any payload here, for anyone.
     Reads go through GlideRecordSecure so the platform's read ACLs are the authority:
     a Submitter reads any request (STRY0012133 ACL); anyone without that rule still only
     ever sees their own, and a record they cannot read answers exactly like a record
     that does not exist (no existence leak). */
  var TABLE = 'x_snc_ptag_engage_engagement_request';

  /* I6 state copy register */
  var CONTEXT = {
    '1':  'Request received and queued for triage.',
    '-1': 'PTAG is validating scope and fit.',
    '-2': 'Review is paused until you add the requested details.',
    '2':  'Accepted and waiting for capacity.',
    '4':  'Scheduled with an owner and a timeline.',
    '5':  'Work in flight with the assigned team.',
    '3':  'Engagement delivered and closed.',
    '7':  'Not moving forward after PTAG review.',
    '8':  'Already tracked under another request.',
    '9':  'Withdrawn before completion.',
    '10': 'Paused by PTAG. Work resumes when the hold is lifted.'
  };

  /* slug -> value + label, hardcoded whitelist */
  var STATES = {
    'submitted':      { value: '1',  label: 'Submitted' },
    'under_review':   { value: '-1', label: 'Under Review' },
    'in_backlog':     { value: '2',  label: 'In Backlog' },
    'planned':        { value: '4',  label: 'Planned' },
    'in_development': { value: '5',  label: 'In Development' },
    'completed':      { value: '3',  label: 'Completed' },
    'need_info':      { value: '-2', label: 'Need more information' },
    'unlikely':       { value: '7',  label: 'Unlikely to implement' },
    'cancelled':      { value: '9',  label: 'Cancelled' },
    'duplicate':      { value: '8',  label: 'Duplicate' },
    'on_hold':        { value: '10', label: 'On Hold' }
  };
  /* B147: journey order = the sys_choice sequence measured on astrodev 2026-09-29
     (orderBy('state') would sort by the stored integer, which is not this order) */
  var JOURNEY = ['1', '-2', '-1', '2', '4', '5', '10', '3', '7', '9', '8'];
  var JPOS = {};
  for (var ji = 0; ji < JOURNEY.length; ji++) { JPOS[JOURNEY[ji]] = ji; }
  /* sort key -> first-click direction (the default for an unknown dir) */
  var SORTS = { number: 'desc', title: 'asc', submitted_by: 'asc', geo: 'asc',
                state: 'asc', submitted: 'desc', updated: 'desc' };
  var VIEW_PREF = 'ptag.hub.myeng.view';
  var MAX_FETCH = 2000;   /* rows read for the sort (prod has ~360 in total) */
  var MAX_ROWS = 1000;    /* rows returned; the client pages over them */
  var MAX_PEOPLE = 200, MAX_GEO = 100;

  data.items = [];
  data.count = 0;
  data.total = 0;
  data.is_guest = !gs.getSession().isLoggedIn();
  if (data.is_guest) { return; }
  data.viewer = String(gs.getUserName());
  var ME = String(gs.getUserID());
  var MY_NAME = '';
  try { MY_NAME = String(gs.getUser().getDisplayName() || ''); } catch (eN) {}
  if (!MY_NAME) { MY_NAME = data.viewer; }
  data.me_name = MY_NAME;
  data.attach = { max_mb: 10, accept: '.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.png,.jpg,.jpeg,.gif,.txt,.csv,.msg,.eml' };
  if (input && input.seq != null) { data.seq = input.seq; }

  var ACCESS = new x_snc_ptag_engage.PTAGHubAccess();

  /* I20: per-user read receipts. B147: only ever for the SUBMITTER's own request, or
     every manager who opens someone else's request would leave a stray receipt. */
  var READ_PREF = 'ptag.hub.read.';
  function markRead(sid) {
    try { gs.getUser().savePreference(READ_PREF + sid, new GlideDateTime().getValue()); }
    catch (e) { /* a receipt is a nicety - never fail a read over one */ }
  }

  function hex32(x) { return /^[0-9a-f]{32}$/.test(String(x || '')); }
  /* GlideRecord.getValue on a boolean answers '1'/'0' in this engine (measured), not 'true' */
  function isTrue(v) { v = String(v); return v === '1' || v === 'true'; }

  /* I30: files on a request (read back only; uploads go browser -> Attachment API) */
  function attachmentsOf(sid) {
    var out = [], names = {};
    var a = new GlideRecord('sys_attachment');
    a.addQuery('table_name', TABLE);
    a.addQuery('table_sys_id', sid);
    a.orderByDesc('sys_created_on');
    a.setLimit(50);
    a.query();
    var me = String(gs.getUserName());
    while (a.next()) {
      var by = String(a.getValue('sys_created_by') || '');
      names[by] = true;
      out.push({
        id: a.getUniqueValue(),
        name: String(a.getValue('file_name') || ''),
        size: parseInt(a.getValue('size_bytes'), 10) || 0,
        type: String(a.getValue('content_type') || ''),
        by: by,
        when: a.getDisplayValue('sys_created_on'),
        mine: by === me
      });
    }
    var resolved = new x_snc_ptag_engage.PTAGCommentSignal().displayNames(Object.keys(names));
    for (var i = 0; i < out.length; i++) {
      out[i].by = resolved[out[i].by] || out[i].by;
    }
    return out;
  }

  /* B147 READ guard: the platform's read ACLs decide (GlideRecordSecure). Missing and
     unreadable answer the same null. */
  function readable(sid) {
    if (!hex32(sid)) { return null; }
    var gr = new GlideRecordSecure(TABLE);
    if (!gr.get(String(sid))) { return null; }
    return gr;
  }

  /* WRITE guard (unchanged): submitter or PTAG roles, via PTAGHubAccess.canAct */
  function guardedGet(sid) {
    if (!hex32(sid)) { return null; }
    var gr = new GlideRecord(TABLE);
    if (!gr.get(String(sid))) { return null; }
    if (!ACCESS.canAct(gr)) { return null; }
    return gr;
  }

  function thread(sid, mine) {
    /* customer-visible journal ONLY: element=comments (work_notes excluded by query -
       that is where AI drafts live). Chronological. */
    var out = [];
    var authors = {};
    var j = new GlideRecord('sys_journal_field');
    j.addQuery('name', TABLE);
    j.addQuery('element_id', sid);
    j.addQuery('element', 'comments');
    j.orderBy('sys_created_on');
    j.setLimit(200);
    j.query();
    while (j.next()) {
      var by = String(j.getValue('sys_created_by') || '');
      out.push({ author: by, when: j.getDisplayValue('sys_created_on'),
                 text: String(j.getValue('value') || '') });
      authors[by] = true;
    }
    var keys = Object.keys(authors);
    var names = {};
    if (keys.length) {
      var u = new GlideRecord('sys_user');
      u.addQuery('user_name', 'IN', keys.join(','));
      u.query();
      while (u.next()) { names[String(u.getValue('user_name'))] = String(u.getValue('name') || ''); }
    }
    var me = String(gs.getUserName());
    new x_snc_ptag_engage.PTAGCommentSignal().markUnanswered(out);
    for (var i = 0; i < out.length; i++) {
      out[i].mine = out[i].author === me;
      out[i].author = names[out[i].author] || out[i].author;
      /* B147: "New" is relative to the requester - no markers on someone else's request */
      if (!mine) { out[i].is_new = false; }
    }
    return out;
  }

  /* ---- I13 R5: journey timeline builder (unchanged) ---- */
  var TL_STEPS = [
    { v: '1',  t: 'Submitted',      s: 'Request received and queued for triage.' },
    { v: '-1', t: 'Under Review',   s: 'PTAG is validating scope and fit.' },
    { v: '2',  t: 'In Backlog',     s: 'Accepted and waiting for capacity.' },
    { v: '4',  t: 'Planned',        s: 'Scheduled with an owner and a timeline.' },
    { v: '5',  t: 'In Development', s: 'Work in flight with the assigned team.' },
    { v: '3',  t: 'Completed',      s: 'Engagement delivered and closed.' }
  ];
  var TL_TERMINAL = {
    '7': { t: 'Unlikely to implement', s: 'Not moving forward after PTAG review.', pred: 2 },
    '8': { t: 'Duplicate',             s: 'Already tracked under another request.', pred: 2 },
    '9': { t: 'Cancelled',             s: 'Withdrawn before completion.', pred: 1 }
  };
  function buildTimeline(st) {
    var nodes = [], i;
    if (TL_TERMINAL[st]) {
      for (i = 0; i < TL_TERMINAL[st].pred; i++) {
        nodes.push({ t: TL_STEPS[i].t, s: TL_STEPS[i].s, cls: 'is-done', neg: false, attn: false });
      }
      nodes.push({ t: TL_TERMINAL[st].t, s: TL_TERMINAL[st].s, cls: 'is-negative', neg: true, attn: false });
      return nodes;
    }
    if (st === '-2') {
      nodes.push({ t: TL_STEPS[0].t, s: TL_STEPS[0].s, cls: 'is-done', neg: false, attn: false });
      nodes.push({ t: TL_STEPS[1].t, s: TL_STEPS[1].s, cls: 'is-done', neg: false, attn: false });
      nodes.push({ t: 'Need more information', s: 'PTAG is waiting on you - check your email and update the request.', cls: 'is-attn', neg: false, attn: true });
      for (i = 2; i < TL_STEPS.length; i++) {
        nodes.push({ t: TL_STEPS[i].t, s: TL_STEPS[i].s, cls: 'is-future', neg: false, attn: false });
      }
      return nodes;
    }
    if (st === '10') {
      for (i = 0; i < 5; i++) {
        nodes.push({ t: TL_STEPS[i].t, s: TL_STEPS[i].s, cls: 'is-done', neg: false, attn: false });
      }
      nodes.push({ t: 'On Hold', s: 'Paused by PTAG. Work resumes when the hold is lifted.', cls: 'is-hold', neg: false, attn: false, hold: true });
      nodes.push({ t: TL_STEPS[5].t, s: TL_STEPS[5].s, cls: 'is-future', neg: false, attn: false });
      return nodes;
    }
    var pos = 0;
    for (i = 0; i < TL_STEPS.length; i++) { if (TL_STEPS[i].v === st) { pos = i; break; } }
    for (i = 0; i < TL_STEPS.length; i++) {
      var cls = (i < pos) ? 'is-done' : ((i === pos) ? 'is-current' : 'is-future');
      if (st === '3') { cls = 'is-done'; }
      nodes.push({ t: TL_STEPS[i].t, s: TL_STEPS[i].s, cls: cls, neg: false, attn: false });
    }
    return nodes;
  }

  function detailOf(gr, mine, canAct) {
    /* WHITELIST ONLY - never widen without a security review.
       No score, no score_band, no scoring_version, no work_notes.
       B147: + Target Geo, Submitted by, mine, can_act (drives the read-only view). */
    var st = String(gr.getValue('state') || '1');
    return {
      id: gr.getUniqueValue(),
      number: gr.getValue('number'),
      short_description: gr.getValue('short_description'),
      state: st,
      state_label: gr.getDisplayValue('state'),
      state_context: CONTEXT[st] || '',
      practice: gr.getDisplayValue('practice'),
      partner: gr.getDisplayValue('partner'),
      geo: gr.getDisplayValue('target_geo'),
      submitted_by: gr.getDisplayValue('opened_by'),
      submitted: gr.getDisplayValue('sys_created_on'),
      updated: gr.getDisplayValue('sys_updated_on'),
      mine: !!mine,
      can_act: !!canAct,
      timeline: buildTimeline(st),
      locked: ACCESS.isLockedState(st),
      comments_locked: ACCESS.isCommentLocked(st)
    };
  }

  if (input && input.action === 'detail') {
    var g1 = readable(input.sys_id);
    if (!g1) { data.error = 'not_authorized'; return; }
    var mine1 = String(g1.getValue('opened_by')) === ME;
    var act1 = ACCESS.canAct(g1);
    data.detail = detailOf(g1, mine1, act1);
    data.thread = thread(g1.getUniqueValue(), mine1);
    data.attachments = attachmentsOf(g1.getUniqueValue());
    /* I20: opening it stops the pulse - your own requests only (B147) */
    if (mine1 && data.thread.length) { markRead(g1.getUniqueValue()); }
    return;
  }

  if (input && input.action === 'attach_list') {
    var g4 = guardedGet(input.sys_id);
    if (!g4) { data.error = 'not_authorized'; return; }
    data.attachments = attachmentsOf(g4.getUniqueValue());
    return;
  }

  if (input && input.action === 'attach_delete') {
    /* I30: three guards - canAct on the request, the attachment hangs off THAT request,
       and the caller uploaded it. Any failure answers the same not_authorized. */
    var g5 = guardedGet(input.sys_id);
    if (!g5) { data.error = 'not_authorized'; return; }
    if (ACCESS.isLocked(g5)) {
      data.error = 'locked';
      data.attachments = attachmentsOf(g5.getUniqueValue());
      return;
    }
    var aid = String(input.attachment_id || '');
    if (!hex32(aid)) { data.error = 'not_authorized'; return; }
    var ar = new GlideRecord('sys_attachment');
    if (!ar.get(aid) ||
        String(ar.getValue('table_name')) !== TABLE ||
        String(ar.getValue('table_sys_id')) !== g5.getUniqueValue() ||
        String(ar.getValue('sys_created_by')) !== String(gs.getUserName())) {
      data.error = 'not_authorized';
      return;
    }
    ar.deleteRecord();
    data.deleted = true;
    data.attachments = attachmentsOf(g5.getUniqueValue());
    return;
  }

  if (input && input.action === 'comment') {
    var g2 = guardedGet(input.sys_id);
    if (!g2) { data.error = 'not_authorized'; return; }
    var mine2 = String(g2.getValue('opened_by')) === ME;
    if (ACCESS.isCommentLockedRec(g2)) {
      data.error = 'locked';
      data.detail = detailOf(g2, mine2, true);
      data.thread = thread(g2.getUniqueValue(), mine2);
      data.attachments = attachmentsOf(g2.getUniqueValue());
      return;
    }
    var txt = String(input.text || '').trim();
    if (!txt) { data.error = 'empty_comment'; return; }
    if (txt.length > 4000) { txt = txt.substring(0, 4000); }
    /* journal append via the GlideElement setter (setValue does not journal) */
    g2.comments = txt;
    if (!g2.update()) { data.error = 'save_failed'; return; }
    data.posted = true;
    data.detail = detailOf(g2, mine2, true);
    data.thread = thread(g2.getUniqueValue(), mine2);
    data.attachments = attachmentsOf(g2.getUniqueValue());
    if (mine2) { markRead(g2.getUniqueValue()); }
    return;
  }

  /* ===================== B147: the saved view ===================== */

  /* Can this viewer read requests other than their own? Asked of the platform, not
     assumed from a role name, so it follows the ACL through go-live (runbook B6). When
     false, every surface below stays "mine only" (no existence leak). */
  var BROWSE = (function() {
    try {
      var s = new GlideRecordSecure(TABLE);
      s.addQuery('opened_by', '!=', ME);
      s.setLimit(1);
      s.query();
      return s.hasNext();
    } catch (e) { return false; }
  })();
  data.browse = BROWSE;

  function toArr(x) {
    var out = [];
    if (!x || typeof x === 'string') { return out; }
    var n = parseInt(x.length, 10) || 0;
    for (var i = 0; i < n; i++) { out.push(x[i]); }
    return out;
  }
  function defaultView() {
    return { v: 1, people: { mode: 'include', ids: ['me'] }, geo: [], state: '',
             sort: { key: 'submitted', dir: 'desc' } };
  }
  function isDefault(v) {
    return v.people.mode === 'include' && v.people.ids.length === 1 && v.people.ids[0] === 'me' &&
           v.geo.length === 0 && !v.state && v.sort.key === 'submitted' && v.sort.dir === 'desc';
  }
  function existing(table, ids) {
    var ok = {};
    if (!ids.length) { return ok; }
    var g = new GlideRecord(table);
    g.addQuery('sys_id', 'IN', ids.join(','));
    g.query();
    while (g.next()) { ok[g.getUniqueValue()] = true; }
    return ok;
  }
  /* Validation (spec 15): parse; drop unknown people/geos (inactive users are KEPT -
     their requests are history); include with nobody -> default people; unknown state
     -> ''; unknown sort -> default sort. */
  function normalize(raw) {
    var res = { view: defaultView(), dropped: 0, bad: false, empty: false };
    var v = raw;
    if (typeof v === 'string') {
      if (!v) { res.empty = true; return res; }
      try { v = JSON.parse(v); } catch (e) { res.bad = true; return res; }
    }
    if (!v || typeof v !== 'object' || Number(v.v) !== 1) { res.bad = true; return res; }
    var out = defaultView();
    var p = v.people || {};
    var mode = String(p.mode || '');
    if (mode === 'include' || mode === 'exclude') {
      var ids = [], seen = {}, raws = toArr(p.ids), i, r;
      for (i = 0; i < raws.length; i++) {
        r = String(raws[i] || '');
        if (r === ME) { r = 'me'; }
        if (r !== 'me' && !hex32(r)) { res.dropped++; continue; }
        if (seen[r]) { continue; }
        seen[r] = true; ids.push(r);
      }
      var real = ids.filter(function(x) { return x !== 'me'; });
      var ok = existing('sys_user', real);
      var kept = ids.filter(function(x) { return x === 'me' || ok[x]; });
      res.dropped += ids.length - kept.length;
      kept = kept.slice(0, MAX_PEOPLE);
      if (mode === 'include' && !kept.length) { kept = ['me']; }
      out.people = { mode: mode, ids: kept };
    }
    var graw = toArr(v.geo), gids = [], gseen = {}, gi, gv;
    for (gi = 0; gi < graw.length; gi++) {
      gv = String(graw[gi] || '');
      if (gv !== 'none' && !hex32(gv)) { res.dropped++; continue; }
      if (gseen[gv]) { continue; }
      gseen[gv] = true; gids.push(gv);
    }
    var greal = gids.filter(function(x) { return x !== 'none'; });
    var gok = existing('cmn_location', greal);
    var gkept = gids.filter(function(x) { return x === 'none' || gok[x]; });
    res.dropped += gids.length - gkept.length;
    out.geo = gkept.slice(0, MAX_GEO);
    var st = String(v.state || '');
    out.state = STATES.hasOwnProperty(st) ? st : '';
    var so = v.sort || {};
    var sk = String(so.key || ''), sd = String(so.dir || '');
    if (SORTS.hasOwnProperty(sk)) {
      out.sort = { key: sk, dir: (sd === 'asc' || sd === 'desc') ? sd : SORTS[sk] };
    }
    res.view = out;
    return res;
  }
  function savePref(val) {
    try { gs.getUser().savePreference(VIEW_PREF, val); } catch (e) { return false; }
    try { return String(gs.getUser().getPreference(VIEW_PREF) || '') === String(val); }
    catch (e2) { return false; }
  }
  function saveView(v) { return savePref(isDefault(v) ? '' : JSON.stringify(v)); }
  function loadSaved() {
    var raw = '';
    try { raw = String(gs.getUser().getPreference(VIEW_PREF) || ''); } catch (e) {}
    var n = normalize(raw);
    var res = { view: n.view, source: (!n.empty && !n.bad && !isDefault(n.view)) ? 'saved' : 'default', notice: '' };
    if (n.dropped) {
      res.notice = n.dropped === 1
        ? '1 person or Geo in your saved view could not be found and was removed.'
        : n.dropped + ' people or Geos in your saved view could not be found and were removed.';
      saveView(n.view);   /* store the cleaned value back (spec 15, step 4) */
    }
    return res;
  }

  /* people x geo scope (never the state) */
  function scopeQuery(v) {
    var parts = [];
    var ids = [];
    for (var i = 0; i < v.people.ids.length; i++) { ids.push(v.people.ids[i] === 'me' ? ME : v.people.ids[i]); }
    if (!BROWSE) {
      parts.push('opened_by=' + ME);
    } else if (v.people.mode === 'include') {
      parts.push('opened_byIN' + ids.join(','));
    } else if (ids.length) {
      parts.push('opened_byNOT IN' + ids.join(',') + '^ORopened_byISEMPTY');
    }
    if (v.geo.length) {
      var real = [], none = false;
      for (var g = 0; g < v.geo.length; g++) {
        if (v.geo[g] === 'none') { none = true; } else { real.push(v.geo[g]); }
      }
      if (real.length && none) { parts.push('target_geoIN' + real.join(',') + '^ORtarget_geoISEMPTY'); }
      else if (real.length) { parts.push('target_geoIN' + real.join(',')); }
      else { parts.push('target_geoISEMPTY'); }
    }
    return parts;
  }
  function applyParts(gr, parts) {
    for (var i = 0; i < parts.length; i++) { gr.addEncodedQuery(parts[i]); }
  }

  /* ---- people picker: distinct submitters across ALL requests (AC4) ---- */
  if (input && input.action === 'people_options') {
    var pga = new GlideAggregate(TABLE);
    if (!BROWSE) { pga.addQuery('opened_by', ME); }
    pga.addAggregate('COUNT');
    pga.groupBy('opened_by');
    pga.query();
    var pcnt = {}, pids = [];
    while (pga.next()) {
      var pid = String(pga.getValue('opened_by') || '');
      if (!pid) { continue; }
      pcnt[pid] = parseInt(pga.getAggregate('COUNT'), 10) || 0;
      if (pid !== ME) { pids.push(pid); }
    }
    var others = [];
    if (pids.length) {
      var pu = new GlideRecord('sys_user');
      pu.addQuery('sys_id', 'IN', pids.join(','));
      pu.query();
      while (pu.next()) {
        others.push({ id: pu.getUniqueValue(), name: String(pu.getValue('name') || pu.getValue('user_name') || ''),
                      active: isTrue(pu.getValue('active')), n: pcnt[pu.getUniqueValue()] || 0 });
      }
    }
    others.sort(function(a, b) {
      var x = a.name.toLowerCase(), y = b.name.toLowerCase();
      return x < y ? -1 : (x > y ? 1 : 0);
    });
    data.people_options = [{ id: 'me', name: MY_NAME, active: true, me: true, n: pcnt[ME] || 0 }].concat(others);
    return;
  }

  /* ---- Geo picker: the controlled regions (PTAGGeo, x_snc_ptag_engage.target_geo_options) in that
     order, counts within the People scope, "Not set" always last and always present (spec 6.2).
     A Geo still held in a saved view but not offered any more is listed after them, so it can be
     cleared. Records holding an older value keep showing it in the table and the detail view. ---- */
  if (input && input.action === 'geo_options') {
    var gv0 = normalize(String(input.view_json || '')).view;
    var inUse = {}, order = [], ctl = {}, cids = [];
    try { cids = new PTAGGeo().options().map(function(o) { return String(o.sys_id); }); } catch (eC) { cids = []; }
    for (var ci = 0; ci < cids.length; ci++) {
      if (!inUse[cids[ci]]) { inUse[cids[ci]] = true; ctl[cids[ci]] = ci; order.push(cids[ci]); }
    }
    for (var si = 0; si < gv0.geo.length; si++) {
      if (gv0.geo[si] !== 'none' && !inUse[gv0.geo[si]]) { inUse[gv0.geo[si]] = true; order.push(gv0.geo[si]); }
    }
    var scoped = { people: gv0.people, geo: [], state: '', sort: gv0.sort };
    var gcnt = {}, gnone = 0;
    var gsc = new GlideAggregate(TABLE);
    applyParts(gsc, scopeQuery(scoped));
    gsc.addAggregate('COUNT');
    gsc.groupBy('target_geo');
    gsc.query();
    while (gsc.next()) {
      var gk = String(gsc.getValue('target_geo') || '');
      var gn = parseInt(gsc.getAggregate('COUNT'), 10) || 0;
      if (gk) { gcnt[gk] = gn; } else { gnone += gn; }
    }
    var glabels = {};
    if (order.length) {
      var gl = new GlideRecord('cmn_location');
      gl.addQuery('sys_id', 'IN', order.join(','));
      gl.query();
      while (gl.next()) { glabels[gl.getUniqueValue()] = String(gl.getValue('name') || gl.getDisplayValue() || ''); }
    }
    var gopts = [];
    for (var oi = 0; oi < order.length; oi++) {
      gopts.push({ id: order[oi], label: glabels[order[oi]] || '(unknown)', n: gcnt[order[oi]] || 0 });
    }
    gopts.sort(function(a, b) {
      var ca = ctl.hasOwnProperty(a.id), cb = ctl.hasOwnProperty(b.id);
      if (ca && cb) { return ctl[a.id] - ctl[b.id]; }
      if (ca !== cb) { return ca ? -1 : 1; }
      var x = a.label.toLowerCase(), y = b.label.toLowerCase();
      return x < y ? -1 : (x > y ? 1 : 0);
    });
    gopts.push({ id: 'none', label: 'Not set', n: gnone });
    data.geo_options = gopts;
    return;
  }

  /* ---- which view is on screen ---- */
  function param(k) { return String($sp.getParameter(k) || ''); }
  var op = String((input && input.op) || '');
  var saved = loadSaved();
  var view = saved.view, source = saved.source, linked = null;
  data.view_saved = true;
  if (saved.notice) { data.view_notice = saved.notice; }

  var numRaw = '', awaitOn = false, stateLink = '';
  if (op === 'view') {
    var nv = normalize(String((input && input.view_json) || ''));
    view = nv.view;
    source = isDefault(view) ? 'default' : 'saved';
    data.view_saved = saveView(view);
  } else if (op === 'reset') {
    view = defaultView();
    source = 'default';
    data.view_saved = savePref('');
  } else if (op === 'number') {
    numRaw = String((input && input.number) || '');
  } else if (op === 'awaiting') {
    awaitOn = true;
  } else if (op === '') {
    /* first load only: the URL can carry a LINKED view */
    numRaw = param('number');
    if (!numRaw) {
      var aw = param('awaiting');
      awaitOn = !!(aw && aw !== '0' && aw !== 'false');
    }
    if (!numRaw && !awaitOn) {
      var sl = param('state');
      if (sl && STATES.hasOwnProperty(sl)) { stateLink = sl; }
    }
  }
  numRaw = numRaw.toUpperCase().replace(/\s+/g, '');

  /* I21: ONE analysis, three consumers - the awaiting link, the row badges, the chip */
  var signal = new x_snc_ptag_engage.PTAGCommentSignal();
  var sig = signal.analyzeMine();

  /* ---- the list query ---- */
  var listParts = [];
  var numParts = null;
  if (numRaw) {
    /* I14 R6 wildcards, B147: across ALL requests the viewer can read (J3) */
    linked = { kind: 'number', label: numRaw };
    var collapsed = numRaw.replace(/\*{2,}/g, '*');
    var charsetOk = /^[PTAG0-9*]+$/.test(collapsed);
    var hasFrag = collapsed.replace(/\*/g, '').length > 0;
    numParts = [];
    if (!charsetOk || !hasFrag) {
      data.number = numRaw; data.number_invalid = true;
      numParts.push(['sys_id', '=', 'invalid']);
    } else if (collapsed.indexOf('*') === -1) {
      if (/^PTAG\d+$/.test(collapsed)) { numParts.push(['number', '=', collapsed]); }
      else { data.number_invalid = true; numParts.push(['sys_id', '=', 'invalid']); }
      data.number = collapsed;
    } else {
      var beginStar = collapsed.charAt(0) === '*';
      var endStar = collapsed.charAt(collapsed.length - 1) === '*';
      var frags = collapsed.split('*').filter(function(f) { return f.length > 0; });
      for (var fi = 0; fi < frags.length; fi++) {
        var nop = 'CONTAINS';
        if (fi === 0 && !beginStar) { nop = 'STARTSWITH'; }
        else if (fi === frags.length - 1 && !endStar) { nop = 'ENDSWITH'; }
        numParts.push(['number', nop, frags[fi]]);
      }
      data.number = collapsed;
    }
    linked.label = data.number || numRaw;
    if (!BROWSE) { listParts.push('opened_by=' + ME); }
  } else if (awaitOn) {
    linked = { kind: 'awaiting', label: 'waiting on your reply' };
    data.awaiting = true;
    listParts.push(sig.ids.length ? ('sys_idIN' + sig.ids.join(',')) : 'sys_id=invalid');
  } else if (stateLink) {
    /* Home "Where your requests stand" counts only YOUR requests, so its links land on yours */
    linked = { kind: 'state', label: 'your ' + STATES[stateLink].label + ' requests', slug: stateLink };
    listParts.push('opened_by=' + ME);
    listParts.push('state=' + STATES[stateLink].value);
  } else {
    listParts = scopeQuery(view);
    if (view.state) { listParts.push('state=' + STATES[view.state].value); }
  }

  var sortKey = linked ? 'submitted' : view.sort.key;
  var sortDir = linked ? 'desc' : view.sort.dir;
  var gr = new GlideRecordSecure(TABLE);
  applyParts(gr, listParts);
  if (numParts) { for (var ni = 0; ni < numParts.length; ni++) { gr.addQuery(numParts[ni][0], numParts[ni][1], numParts[ni][2]); } }
  var DBORD = { number: 'number', title: 'short_description', submitted: 'sys_created_on', updated: 'sys_updated_on' };
  if (DBORD[sortKey]) {
    if (sortDir === 'asc') { gr.orderBy(DBORD[sortKey]); } else { gr.orderByDesc(DBORD[sortKey]); }
  } else { gr.orderByDesc('sys_created_on'); }
  gr.setLimit(MAX_FETCH);
  gr.query();
  var rows = [];
  while (gr.next()) {
    var ob = String(gr.getValue('opened_by') || '');
    rows.push({
      id: gr.getUniqueValue(),
      number: String(gr.getValue('number') || ''),
      short_description: gr.getValue('short_description'),
      state: String(gr.getValue('state') || '1'),
      state_label: gr.getDisplayValue('state'),
      practice: gr.getDisplayValue('practice'),
      created: gr.getDisplayValue('sys_created_on'),
      updated: gr.getDisplayValue('sys_updated_on'),
      c_raw: String(gr.getValue('sys_created_on') || ''),
      u_raw: String(gr.getValue('sys_updated_on') || ''),
      by_id: ob,
      by: gr.getDisplayValue('opened_by'),
      mine: ob === ME,
      geo_id: String(gr.getValue('target_geo') || ''),
      geo: gr.getDisplayValue('target_geo')
    });
  }
  var total = rows.length;
  if (total >= MAX_FETCH) {
    var tga = new GlideAggregate(TABLE);
    applyParts(tga, listParts);
    if (numParts) { for (var nj = 0; nj < numParts.length; nj++) { tga.addQuery(numParts[nj][0], numParts[nj][1], numParts[nj][2]); } }
    tga.addAggregate('COUNT');
    tga.query();
    if (tga.next()) { total = parseInt(tga.getAggregate('COUNT'), 10) || total; }
  }

  /* sort in script: exact semantics (journey order for State, "Not set" last for Geo in
     BOTH directions, tie-break Number descending) */
  function lc(s) { return String(s || '').toLowerCase(); }
  function keyOf(r) {
    switch (sortKey) {
      case 'number': return r.number;
      case 'title': return lc(r.short_description);
      case 'submitted_by': return lc(r.by);
      case 'geo': return lc(r.geo);
      case 'state': return JPOS.hasOwnProperty(r.state) ? JPOS[r.state] : 99;
      case 'updated': return r.u_raw;
      default: return r.c_raw;
    }
  }
  var sdir = sortDir === 'asc' ? 1 : -1;
  rows.sort(function(a, b) {
    if (sortKey === 'geo') {
      var ae = !a.geo, be = !b.geo;
      if (ae !== be) { return ae ? 1 : -1; }
    }
    var x = keyOf(a), y = keyOf(b), r = 0;
    if (x < y) { r = -1; } else if (x > y) { r = 1; }
    r = r * sdir;
    if (r === 0) { r = a.number < b.number ? 1 : (a.number > b.number ? -1 : 0); }
    return r;
  });
  if (rows.length > MAX_ROWS) { rows = rows.slice(0, MAX_ROWS); }
  for (var ri = 0; ri < rows.length; ri++) { delete rows[ri].c_raw; delete rows[ri].u_raw; }
  data.items = rows;
  data.count = rows.length;
  data.total = total;
  data.truncated = total > rows.length;
  if (data.number && data.count === 0) { data.number_not_found = true; }

  /* ---- I21: viewer-relative comment signal, projected onto YOUR rows only ---- */
  (function() {
    var names = {}, pend = [], i;
    for (i = 0; i < data.items.length; i++) {
      var it = data.items[i];
      var st = it.mine ? sig.map[it.id] : null;
      it.comments = st ? st.total : 0;
      it.unanswered = st ? st.unanswered : 0;
      it.reply_pending = !!(st && st.pending);
      it.unread = !!(st && st.unread);
      if (it.reply_pending) {
        it.last_by = st.last_by;
        names[st.last_by] = true;
        pend.push(it);
      }
    }
    var resolved = signal.displayNames(Object.keys(names));
    for (i = 0; i < pend.length; i++) {
      pend[i].last_by = resolved[pend[i].last_by] || pend[i].last_by;
    }
  })();
  data.awaiting_records = sig.records;
  data.awaiting_comments = sig.comments;

  /* ---- state chips: counts over the view's People x Geo scope, ignoring the state
     itself, so "All N" equals the table total when no chip is active (spec 4) ---- */
  (function() {
    var counts = {}, all = 0;
    var ga = new GlideAggregate(TABLE);
    applyParts(ga, scopeQuery(view));
    ga.addAggregate('COUNT');
    ga.groupBy('state');
    ga.query();
    while (ga.next()) {
      var n = parseInt(ga.getAggregate('COUNT'), 10) || 0;
      counts[String(ga.getValue('state'))] = n;
      all += n;
    }
    var HAPPY = ['submitted', 'under_review', 'in_backlog', 'planned', 'in_development', 'completed'];
    var BRANCH = ['need_info', 'unlikely', 'duplicate', 'cancelled'];
    data.chips = [{ slug: '', label: 'All', count: all, all: true }];
    if (sig.records) {
      data.chips.push({ slug: '__awaiting__', label: 'Awaiting your reply', count: sig.records, awaiting: true });
    }
    var i, s;
    for (i = 0; i < HAPPY.length; i++) {
      s = HAPPY[i];
      data.chips.push({ slug: s, value: STATES[s].value, label: STATES[s].label, count: counts[STATES[s].value] || 0 });
      if (s === 'in_development' && (counts[STATES.on_hold.value] || view.state === 'on_hold')) {
        data.chips.push({ slug: 'on_hold', value: STATES.on_hold.value, label: STATES.on_hold.label,
                          count: counts[STATES.on_hold.value] || 0, branch: true });
      }
    }
    for (i = 0; i < BRANCH.length; i++) {
      s = BRANCH[i];
      /* a saved branch state keeps its chip even at 0, so it can be seen and cleared */
      if (counts[STATES[s].value] || view.state === s) {
        data.chips.push({ slug: s, value: STATES[s].value, label: STATES[s].label, count: counts[STATES[s].value] || 0, branch: true });
      }
    }
  })();

  /* ---- labels for the triggers, chips and the sentence (names resolved on read) ---- */
  (function() {
    var people = [], real = [], i;
    for (i = 0; i < view.people.ids.length; i++) { if (view.people.ids[i] !== 'me') { real.push(view.people.ids[i]); } }
    var names = {};
    if (real.length) {
      var u = new GlideRecord('sys_user');
      u.addQuery('sys_id', 'IN', real.join(','));
      u.query();
      while (u.next()) {
        names[u.getUniqueValue()] = { name: String(u.getValue('name') || u.getValue('user_name') || ''),
                                      active: isTrue(u.getValue('active')) };
      }
    }
    for (i = 0; i < view.people.ids.length; i++) {
      var id = view.people.ids[i];
      if (id === 'me') { people.push({ id: 'me', name: MY_NAME, active: true, me: true }); }
      else { people.push({ id: id, name: (names[id] && names[id].name) || 'Unknown person', active: !!(names[id] && names[id].active) }); }
    }
    var geo = [], greal = [];
    for (i = 0; i < view.geo.length; i++) { if (view.geo[i] !== 'none') { greal.push(view.geo[i]); } }
    var gn = {};
    if (greal.length) {
      var l = new GlideRecord('cmn_location');
      l.addQuery('sys_id', 'IN', greal.join(','));
      l.query();
      while (l.next()) { gn[l.getUniqueValue()] = String(l.getValue('name') || ''); }
    }
    for (i = 0; i < view.geo.length; i++) {
      geo.push({ id: view.geo[i], label: view.geo[i] === 'none' ? 'Not set' : (gn[view.geo[i]] || 'Unknown Geo') });
    }
    data.view_labels = { people: people, geo: geo };
  })();

  data.view = view;
  data.view_source = linked ? 'link' : source;
  data.view_is_default = isDefault(view);
  data.linked = linked;
  data.active = linked ? (linked.kind === 'awaiting' ? '__awaiting__' : null) : (view.state || '');
})();
